def sub(id,kind,asset,appearance,geometry,scale,movement):
    return dict(id=id,kind=kind,asset_hint=asset,appearance=appearance,geometry_and_material=geometry,scale_and_accuracy=scale,movement=movement)
def shot(id,a,b,kind,p0,p1,target0,target1,subjects,anim,timer,metric,v0,v1,unit='',sway=0,impact=None,fov=38):
    camera=dict(projection='perspective',fov_or_scale=fov,keyframes=[dict(t_s=a,position=p0,look_at=target0,ease='smoothstep'),dict(t_s=b,position=p1,look_at=target1,ease='smoothstep')],movement=kind,lens_notes='Keep focal action within y=400..1180 and captions below; continuous parallax.')
    if sway: camera['handheld_sway']=sway
    if impact: camera['impulse_shake']=dict(at_s=impact,duration_s=.65,intensity=.85)
    return dict(id=id,start_s=a,end_s=b,shot_type=kind,world='Earth radius = 1 local unit; black starfield.' if 'orbit' in kind else '1 unit = 1 metre; physical set; sky environment or architectural interior, depth fog.',camera=camera,
        subjects=subjects,animation_plan=anim,lighting='Cool hemisphere fill and warm directional/area key; practical emissives, soft shadows, physical materials.',effects=['ACES grade','restrained HDR bloom','deterministic motion'],composition_notes='HUD x=90 y=240. Caption baseline y=1320. Avoid focal action under captions. Medium views of dynamic people, never a held frozen back-of-head.',
        hud_telemetry=dict(timer_label=timer,metric_label=metric,start_value=v0,end_value=v1,unit=unit,alert_level='critical' if a<21.1 else 'normal'))
