    return dict(id=f'S{i:02}',beat=beat,start_s=a,end_s=b,narration=dict(text=text,start_s=a+.05,end_s=b-.18,delivery_note='Intimate documentary voice. Short clause pauses. No shouted or sexualised delivery.',pacing_energy=energy),viewer_question=question,visual_payoff=payoff,shots=shots,claim_ids=claims,caption_emphasis=[dict(phrase=x,treatment='accent_color') for x in emphasis],audio_cues=cues or [],transition_out=dict(type=transition,duration_s=.35 if transition=='cross_dissolve' else 0,motivation='Match physical movement, light or perspective to the next consequence.'))
